 selects=[('mech', T('배정 방식', 'Assignment method'), [('queue', T('선착순 고르기', 'First come, first served')), ('rsd', T('추첨 순번대로 고르기', 'Lottery order')), ('boston', T('보스턴 방식 (바로 확정)', 'Boston (immediate)')), ('da', T('지연 수락 방식 (게일-섀플리)', 'Deferred acceptance (Gale-Shapley)'))], 'boston', T('위 그림과 "내 아이 시험"이 이 방식으로 바뀝니다. 아래 그래프는 네 방식을 모두 보여 줍니다', 'The animation and the "my child" test follow this method. The charts below always show all four'))],
